function renderCharts(list){const employees={};list.forEach(o=>{employees[o.ownerName]??={name:o.ownerName,total:0,count:0};employees[o.ownerName].total+=o.amount;employees[o.ownerName].count++});const people=Object.values(employees).sort((a,b)=>b.total-a.total),max=Math.max(1,...people.map(x=>x.total)),countMax=Math.max(1,...people.map(x=>x.count)),statuses=[['Chờ xử lý','pending'],['Giao thành công','delivered'],['Hoàn trả','returned']].map(([name,key])=>({name,count:list.filter(o=>o.status===key).length,key}));$('view').innerHTML=`<div class="charts-grid"><section class="card panel"><div class="panelhead"><div><h2>Giá trị theo nhân viên</h2><p>Doanh thu được ghi nhận</p></div></div>${people.length?people.map(x=>`<div class="chart-row"><div><span>${esc(x.name)}</span><strong>${money(x.total)}</strong></div><div class="bar-track"><i class="bar-blue" style="width:${Math.max(4,x.total/max*100)}%"></i></div></div>`).join(''):'<div class="empty">Chưa có dữ liệu</div>'}</section><section class="card panel"><div class="panelhead"><div><h2>Trạng thái đơn hàng</h2><p>Phân bố theo tiến độ</p></div></div>${statuses.map(x=>`<div class="chart-row"><div><span class="badge ${x.key}">${x.name}</span><strong>${x.count} đơn</strong></div><div class="bar-track"><i class="bar-${x.key}" style="width:${list.length?Math.max(x.count?4:0,x.count/list.length*100):0}%"></i></div></div>`).join('')}</section><section class="card panel"><div class="panelhead"><div><h2>Số đơn theo nhân viên</h2><p>Khối lượng xử lý</p></div></div>${people.map(x=>`<div class="chart-row"><div><span>${esc(x.name)}</span><strong>${x.count} đơn</strong></div><div class="bar-track"><i class="bar-green" style="width:${Math.max(4,x.count/countMax*100)}%"></i></div></div>`).join('')||'<div class="empty">Chưa có dữ liệu</div>'}</section><section class="card panel"><div class="panelhead"><div><h2>Top đơn giá trị cao</h2><p>5 đơn cần theo dõi</p></div></div>${[...list].sort((a,b)=>b.amount-a.amount).slice(0,5).map((o,i)=>`<div class="chart-row top-row"><span class="rank">0${i+1}</span><span class="top-code">${esc(o.code)}<small>${esc(o.ownerName)}</small></span><strong class="top-value">${money(o.amount)}</strong></div>`).join('')||'<div class="empty">Chưa có dữ liệu</div>'}</section></div>`}
'@
if (-not $s.Contains($marker)) { throw 'Chart insertion point missing' }
if (-not $s.Contains('function renderCharts(list)')) { $s = $s.Replace($marker, $chart + $marker) }
$accountMarker = ').join('''')}</div></section>`;if($(''userForm''))'
