).join('')}</div></section><section class="card panel perm-panel"><div class="panelhead"><div><h2>Bảng phân quyền chi tiết theo vai trò</h2><p class="permission-note">Quyền trong bản dùng thử áp dụng theo vai trò tài khoản.</p></div></div><div class="table-wrap"><table class="perm-table"><thead><tr><th>Chức năng / Quyền</th><th>ADMIN</th><th>MANAGER</th><th>STAFF</th></tr></thead><tbody><tr><td>Xem đơn hàng</td><td class="perm-yes">✓ Tất cả</td><td class="perm-yes">✓ Tất cả</td><td class="perm-limited">Chỉ của mình</td></tr><tr><td>Tạo đơn hàng</td><td class="perm-yes">✓ Có</td><td class="perm-yes">✓ Có</td><td class="perm-yes">✓ Tự gán tên</td></tr><tr><td>Chỉnh sửa đơn hàng</td><td class="perm-yes">✓ Tất cả</td><td class="perm-yes">✓ Tất cả</td><td class="perm-limited">✓ Đơn của mình</td></tr><tr><td>Xóa đơn hàng</td><td class="perm-yes">✓ Có</td><td class="perm-no">✕ Không</td><td class="perm-limited">✓ Đơn của mình</td></tr><tr><td>Xuất báo cáo CSV</td><td class="perm-yes">✓ Tất cả</td><td class="perm-yes">✓ Tất cả</td><td class="perm-limited">✓ Đơn của mình</td></tr><tr><td>Quản lý người dùng</td><td class="perm-yes">✓ Tạo / khóa tài khoản</td><td class="perm-limited">✓ Chỉ xem</td><td class="perm-no">✕ Không xem</td></tr><tr><td>Chia doanh thu</td><td class="perm-yes">✓ Có</td><td class="perm-yes">✓ Có</td><td class="perm-no">✕ Không</td></tr></tbody></table></div></section>`;if($(''userForm''))
